import{_ as n,o as r,c as a,a2 as i}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Server Managers & Provisioning","description":"","frontmatter":{},"headers":[],"relativePath":"admin/servers.md","filePath":"admin/servers.md"}'),t={name:"admin/servers.md"};function o(s,e,l,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="server-managers-provisioning" tabindex="-1">Server Managers &amp; Provisioning <a class="header-anchor" href="#server-managers-provisioning" aria-label="Permalink to &quot;Server Managers &amp; Provisioning&quot;">​</a></h1><p>FOSSBilling automates the lifecycle of hosting accounts by connecting directly to remote server managers.</p><hr><h2 id="🖥️-supported-server-managers" tabindex="-1">🖥️ Supported Server Managers <a class="header-anchor" href="#🖥️-supported-server-managers" aria-label="Permalink to &quot;🖥️ Supported Server Managers&quot;">​</a></h2><p>FOSSBilling includes high-performance drivers for the following platforms:</p><h3 id="whm-cpanel-and-fossbilling" tabindex="-1">WHM / cPanel and FOSSBilling <a class="header-anchor" href="#whm-cpanel-and-fossbilling" aria-label="Permalink to &quot;WHM / cPanel and FOSSBilling&quot;">​</a></h3><p>cPanel is the industry standard for shared hosting.</p><ul><li><strong>Connection:</strong> Uses the WHM JSON API v1.</li><li><strong>Requirements:</strong> A valid WHM API Token with <code>create-acct</code>, <code>manage-accounts</code>, and <code>modify-accounts</code> permissions.</li><li><strong>Automated Actions:</strong> Account creation, suspension for non-payment, and termination.</li></ul><h3 id="hestiacp-and-fossbilling" tabindex="-1">HestiaCP and FOSSBilling <a class="header-anchor" href="#hestiacp-and-fossbilling" aria-label="Permalink to &quot;HestiaCP and FOSSBilling&quot;">​</a></h3><p>A popular open-source control panel for VPS and dedicated servers.</p><ul><li><strong>Connection:</strong> Uses the Hestia CLI-over-API gateway.</li><li><strong>Requirements:</strong> API Access enabled in Hestia settings and an Access Key/Secret pair.</li><li><strong>Features:</strong> Supports automated user creation and web domain assignment.</li></ul><h3 id="cwp-centos-web-panel-and-fossbilling" tabindex="-1">CWP (CentOS Web Panel) and FOSSBilling <a class="header-anchor" href="#cwp-centos-web-panel-and-fossbilling" aria-label="Permalink to &quot;CWP (CentOS Web Panel) and FOSSBilling&quot;">​</a></h3><p>A powerful free/pro panel for RPM-based distributions.</p><ul><li><strong>Connection:</strong> Uses the CWP REST API v1.</li><li><strong>Requirements:</strong> API Key generated from the CWP admin dashboard.</li><li><strong>Port:</strong> Default communication occurs over port <code>2304</code>.</li></ul><h3 id="directadmin-and-fossbilling" tabindex="-1">DirectAdmin and FOSSBilling <a class="header-anchor" href="#directadmin-and-fossbilling" aria-label="Permalink to &quot;DirectAdmin and FOSSBilling&quot;">​</a></h3><p>A lightweight and fast control panel alternative.</p><ul><li><strong>Connection:</strong> Uses the <code>CMD_API</code> interface.</li><li><strong>Authentication:</strong> Supports both Login Keys and standard administrator credentials.</li></ul><hr><h2 id="🔧-other-server-managers" tabindex="-1">🔧 Other Server Managers <a class="header-anchor" href="#🔧-other-server-managers" aria-label="Permalink to &quot;🔧 Other Server Managers&quot;">​</a></h2><p>If your control panel is not listed above, FOSSBilling offers two flexible alternatives:</p><h3 id="_1-plesk-rest-v2" tabindex="-1">1. Plesk REST v2 <a class="header-anchor" href="#_1-plesk-rest-v2" aria-label="Permalink to &quot;1. Plesk REST v2&quot;">​</a></h3><p>Modern driver for Windows and Linux Plesk nodes using the latest JSON REST API for subscription management.</p><h3 id="_2-custom-webhook-provisioner" tabindex="-1">2. Custom Webhook Provisioner <a class="header-anchor" href="#_2-custom-webhook-provisioner" aria-label="Permalink to &quot;2. Custom Webhook Provisioner&quot;">​</a></h3><p>For advanced users with custom infrastructure (Kubernetes, Proxmox, or bespoke scripts).</p><ul><li><strong>How it works:</strong> FOSSBilling sends a POST request with a JSON payload containing order details to your endpoint.</li><li><strong>Security:</strong> Supports custom headers and HMAC signature verification.</li></ul><hr><h2 id="🧪-testing-connectivity" tabindex="-1">🧪 Testing Connectivity <a class="header-anchor" href="#🧪-testing-connectivity" aria-label="Permalink to &quot;🧪 Testing Connectivity&quot;">​</a></h2><p>Before assigning a server to a product, use the <strong>Test Connection</strong> button in the server management view. This perform a real-time handshake with the remote API to ensure:</p><ol><li>The server is reachable over the network.</li><li>The API credentials have the correct permissions.</li><li>The server manager is responding with the expected protocol version.</li></ol>',29)])])}const u=n(t,[["render",o]]);export{p as __pageData,u as default};
